import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { millingSpotPositions } from "../.test-dist/lib/millingLiveView.js";

// Expected coordinates were generated by glasgow_service.exposure_lattice
// build_lattice + lattice_points, including segment boundaries and DAC merging.
const cases=JSON.parse(readFileSync(new URL("./fixtures/exposureSpotGolden.json",import.meta.url),"utf8"));
for(const [i,{request,expected}] of cases.entries()) {
  test(`exposure feedback matches service spot order: ${request.shape.kind}, ${request.axis}, case ${i}`,()=>{
    assert.deepEqual([...millingSpotPositions(request)],expected);
  });
}
